///|
test "DATA producer reuse preserves explicit prefix and terminal Result owners" {
  // Authored independently from the existing DATA and RESULT contracts:
  // one producer and one stage; original retains its prefix, while active
  // names the final filtered result. DATA itself adds no exported result.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":2}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_0"},{"from":"aql_data_0","select":["id"],"as":"aql_result_checkpoint_0"},{"filter":{"gt":[{"field":"id"},{"literal":0}]}},{"select":["id"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["id"]},"aql_retained_result_0":{"from":"aql_result_checkpoint_0","fields":["id"]}}}],"results":{"original":{"from":{"stage":"main","result":"aql_retained_result_0"}},"active":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  let script = @query.parse_query_script(
    "DATA n = SELECT 2 AS id; FROM n |> RESULT original |> WHERE id > 0 |> RESULT active",
    syntax_limits(),
  ).unwrap()
  let program = compile_query_script(
    script,
    { ..fixture_context(), inputs: [], },
    construction_limits(),
  ).unwrap()
  assert_eq(semantic(program), semantic(expected))
  assert_eq(@program.stage_count(program), 1)
  assert_eq(@program.export_count(program), 2)
  match
    @check.check_parsed(program, check_environment(), None, check_limits()) {
    Checked(_) => ()
    NeedsInputs(_) => fail("DATA does not introduce an acquisition")
    Rejected(diagnostic) => raise @check.diagnostic_cause(diagnostic)
  }
}

///|
test "DATA binding does not discard illegal nested Result declarations" {
  let nested = @query.parse_query_script(
    "DATA n = SELECT 2 AS id |> RESULT hidden; FROM n |> SELECT id",
    syntax_limits(),
  ).unwrap()
  assert_true(
    compile_query_script(
      nested,
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    is Err(UnsupportedResult),
  )
  let script = @query.parse_query_script(
    "DATA n = SELECT 2 AS id; FROM n |> RESULT saved |> WHERE id > 0 |> RESULT `SAVED`",
    syntax_limits(),
  ).unwrap()
  assert_true(
    compile_query_script(
      script,
      { ..fixture_context(), inputs: [], },
      construction_limits(),
    )
    is Err(DuplicateOutput),
  )
}

///|
fn data_acquisition_environment() -> @check.CheckEnvironment {
  @check.checking_environment(
    @check.checking_environment_wire(check_environment()),
    { text_time: false, veca: false, },
    { rela: true, sga: false, tea: false, calendar: false, text_rank: false, },
    graph=true,
  )
}

///|
test "DATA imports the existing input once without adding a DATA capture" {
  let text = "DATA kept = FROM orders |> SELECT id; FROM kept |> SELECT id"
  let actual = compile_query_script(
    @query.parse_query_script(text, syntax_limits()).unwrap(),
    fixture_context(),
    construction_limits(),
  ).unwrap()
  // This is authored from the existing input/step contract. DATA creates a
  // logical producer in main, not another acquisition or exported Result.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{"orders":{"carrier":"relation","schema":{"id":{"type":"string","nullable":false},"customer_id":{"type":"string","nullable":false},"status":{"type":"string","nullable":false},"amount":{"type":"number","nullable":false}},"primary_key":["id"]}},"steps":[{"from":"orders","select":["id"],"as":"aql_data_1"},{"from":"aql_data_1","select":["id"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["id"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  assert_eq(semantic(actual), semantic(expected))
  assert_eq(@program.stage_count(actual), 1)
  for program in [actual, expected] {
    match
      @check.check_parsed(
        program,
        data_acquisition_environment(),
        None,
        check_limits(),
      ) {
      Checked(_) => ()
      Rejected(diagnostic) => raise @check.diagnostic_cause(diagnostic)
      NeedsInputs(_) => fail("schema input is already declared")
    }
  }
}

///|
test "DATA preserves the requested capture Result and complete schema" {
  let text = "DATA kept = FROM orders |> SELECT id; FROM kept |> SELECT id"
  let actual = compile_query_script(
    @query.parse_query_script(text, syntax_limits()).unwrap(),
    { ..fixture_context(), captured_stage: Some("capture"), },
    construction_limits(),
  ).unwrap()
  // DATA does not move its projection or predicate into the acquisition.
  // That same complete captured Result can serve another DATA consumer.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"capture","inputs":{"orders":{"carrier":"relation","schema":{"id":{"type":"string","nullable":false},"customer_id":{"type":"string","nullable":false},"status":{"type":"string","nullable":false},"amount":{"type":"number","nullable":false}},"primary_key":["id"]}},"steps":[{"from":"orders","filter":{"literal":true}},{"select":["id","customer_id","status","amount"],"as":"aql_capture_0"}],"results":{"source":{"from":"aql_capture_0","fields":["id","customer_id","status","amount"]}}},{"id":"main","inputs":{"orders":{"result":{"stage":"capture","result":"source"}}},"steps":[{"from":"orders","select":["id"],"as":"aql_data_1"},{"from":"aql_data_1","select":["id"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["id"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  assert_eq(semantic(actual), semantic(expected))
  assert_eq(@program.stage_count(actual), 2)
  assert_eq(@program.export_count(actual), 1)
  for program in [actual, expected] {
    match
      @check.check_parsed(
        program,
        data_acquisition_environment(),
        None,
        check_limits(),
      ) {
      Checked(_) => ()
      Rejected(diagnostic) => raise @check.diagnostic_cause(diagnostic)
      NeedsInputs(_) => fail("capture uses the admitted schema input")
    }
  }
}

///|
test "DATA set and constructor references reuse one captured input" {
  let context = { ..fixture_context(), captured_stage: Some("capture"), }
  for
    (text, needs_source_view) in [
      (
        "DATA kept = FROM orders |> WHERE amount > 10 |> SELECT id; DATA combined = FROM kept |> SELECT id |> UNION ALL (FROM orders |> SELECT id); FROM combined |> SELECT id",
        false,
      ),
      (
        "DATA g = PROPERTY GRAPH (NODE TABLES (orders AS Person KEY (id) LABEL Person PROPERTIES (id), orders AS Company KEY (id) LABEL Company PROPERTIES (id))); FROM GRAPH g |> MATCH (a:Person) |> SELECT a.id",
        true,
      ),
    ] {
    let program = compile_query_script(
      @query.parse_query_script(text, syntax_limits()).unwrap(),
      context,
      construction_limits(),
    ).unwrap()
    let body = semantic(program)
    assert_eq(@program.stage_count(program), 2)
    assert_eq(@program.export_count(program), 1)
    assert_eq(body.split("\"carrier\":\"relation\"").length(), 2)
    assert_eq(body.split("\"stage\":\"capture\"").length(), 2)
    assert_true(body.contains("\"filter\":{\"literal\":true}"))
    match
      @check.check_parsed(
        program,
        data_acquisition_environment(),
        None,
        check_limits(),
      ) {
      Checked(_) => assert_false(needs_source_view)
      Rejected(diagnostic) =>
        match @check.diagnostic_cause(diagnostic) {
          Source(SourceView(Program(Program(Pipeline(_, issue))))) => {
            // The bare schema fixture is not an admitted Source View. Retain
            // the common owner's refusal; DATA cannot grant Graph provenance.
            assert_true(needs_source_view)
            assert_eq(issue.kind, MissingPropertyProducerDefinition)
          }
          other => raise other
        }
      NeedsInputs(_) => fail("all declared sources remain in the Program")
    }
  }
}

///|
test "DATA imports only used inputs and preserves input and Stage budgets" {
  let context = fixture_context()
  let extra = {
    ..context.inputs[0],
    name: "unused",
    relation: [{ value: "unused", quoted: false, }],
  }
  let script = @query.parse_query_script(
    "DATA kept = FROM orders |> SELECT id; FROM kept |> SELECT id",
    syntax_limits(),
  ).unwrap()
  let program = compile_query_script(
    script,
    {
      ..context,
      inputs: [context.inputs[0], extra],
      captured_stage: Some("capture"),
    },
    construction_limits(),
  ).unwrap()
  assert_false(semantic(program).contains("unused"))
  assert_eq(@program.stage_count(program), 2)
  assert_true(
    compile_query_script(
      script,
      { ..context, captured_stage: Some("capture"), },
      {
        ..construction_limits(),
        program: { ..construction_limits().program, max_stages: 1, },
      },
    )
    is Err(Admission(_)),
  )
  for
    bad in [
      { ..context, captured_stage: Some(""), },
      { ..context, captured_stage: Some("main"), },
      { ..context, inputs: [context.inputs[0], context.inputs[0]], },
      { ..context, inputs: [{ ..context.inputs[0], visible_fields: ["id"], }], },
      {
        ..context,
        inputs: [
          { ..context.inputs[0], source: StageResult("missing", "rows"), },
        ],
      },
    ] {
    assert_true(
      compile_query_script(script, bad, construction_limits())
      is Err(InvalidContext),
    )
  }
}

///|
test "DATA capture preserves published Relation names and DATA alias names" {
  let context = { ..fixture_context(), captured_stage: Some("capture"), }
  for
    text in [
      "DATA g = PROPERTY GRAPH (NODE TABLES (`orders` AS Person KEY (id) LABEL Person PROPERTIES (id), `orders` AS Company KEY (id) LABEL Company PROPERTIES (id))); FROM GRAPH g |> MATCH (a:Person) |> SELECT a.id",
      "DATA saved = FROM orders |> SELECT id; DATA g = PROPERTY GRAPH (NODE TABLES (saved AS Person KEY (id) LABEL Person PROPERTIES (id), `SAVED` AS Company KEY (id) LABEL Company PROPERTIES (id))); FROM GRAPH g |> MATCH (a:Person) |> SELECT a.id",
    ] {
    let program = compile_query_script(
      @query.parse_query_script(text, syntax_limits()).unwrap(),
      context,
      construction_limits(),
    ).unwrap()
    assert_eq(@program.stage_count(program), 2)
    assert_eq(semantic(program).split("\"carrier\":\"relation\"").length(), 2)
  }
  assert_true(
    exact_unresolved_relation(
      compile_query_script(
        @query.parse_query_script(
          "DATA g = PROPERTY GRAPH (NODE TABLES (orders AS Person KEY (id) LABEL Person PROPERTIES (id), `ORDERS` AS Company KEY (id) LABEL Company PROPERTIES (id))); FROM GRAPH g |> MATCH (a:Person) |> SELECT a.id",
          syntax_limits(),
        ).unwrap(),
        context,
        construction_limits(),
      ),
      [("ORDERS", true)],
    ),
  )
}

///|
fn checked_data_join(
  text : String,
  context : Context,
) -> @program.Program raise {
  let program = compile_query_script(
    @query.parse_query_script(text, syntax_limits()).unwrap(),
    context,
    construction_limits(),
  ).unwrap()
  match
    @check.check_parsed(program, check_environment(), None, check_limits()) {
    Checked(_) => ()
    Rejected(error) => raise @check.diagnostic_cause(error)
    _ => fail("DATA JOIN must retain its declared producers")
  }
  program
}

///|
test "DATA SQL and Pipe JOIN reuse existing logical producer inputs" {
  // Independently authored existing Values/projection/cross_join Program.
  // There is no acquisition or Stage boundary between these DATA bindings.
  let expected = @program.parse(
    (
      #|{"version":"actql/0.1","id":"fixture.query_pair","stages":[{"id":"main","inputs":{},"steps":[{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_1"},{"from":"aql_script_seed_1","derive":{"aql_query_expr_0":{"literal":1}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_0"},{"values":{"schema":{"aql_source_free_unit":{"type":"boolean","nullable":false}},"rows":[{"aql_source_free_unit":true}]},"as":"aql_script_seed_3"},{"from":"aql_script_seed_3","derive":{"aql_query_expr_0":{"literal":2}}},{"select":[{"id":"aql_query_expr_0"}],"as":"aql_data_2"},{"from":"aql_data_0","cross_join":{"with":"aql_data_2","max_output_rows":1000,"select":{"a":"left.id","b":"right.id"}},"as":"aql_join_output_6"},{"from":"aql_join_output_6","select":["a","b"],"as":"aql_script_result"}],"results":{"rows":{"from":"aql_script_result","fields":["a","b"]}}}],"results":{"answer":{"from":{"stage":"main","result":"rows"}}}}
    ),
    construction_limits().program,
    format=Json,
  ).unwrap()
  for
    body in [
      "SELECT l.id AS a, r.id AS b FROM lefts AS l CROSS JOIN rights AS r", "FROM lefts AS l |> CROSS JOIN rights AS r |> SELECT l.id AS a, r.id AS b",
    ] {
    let program = checked_data_join(
      "DATA lefts = SELECT 1 AS id; DATA rights = SELECT 2 AS id; DATA paired = " +
      body +
      "; FROM paired |> SELECT a, b",
      { ..fixture_context(), inputs: [], },
    )
    assert_eq(semantic(program), semantic(expected))
    assert_eq(@program.stage_count(program), 1)
  }
}

///|
test "several DATA JOINs have disjoint bindings and share one capture" {
  for
    text in [
      "DATA lefts = FROM orders |> SELECT id; DATA first = SELECT l.id FROM lefts AS l JOIN lefts AS r ON l.id = r.id; DATA second = SELECT l.id FROM first AS l JOIN lefts AS r ON l.id = r.id; FROM second |> SELECT id",
      "DATA joined = WITH seed AS (FROM orders |> SELECT id) SELECT l.id FROM seed AS l JOIN seed AS r ON l.id = r.id; FROM joined |> SELECT id",
    ] {
    let program = checked_data_join(text, {
      ..fixture_context(),
      captured_stage: Some("capture"),
    })
    assert_eq(@program.stage_count(program), 2)
    assert_eq(@program.export_count(program), 1)
    let body = semantic(program)
    assert_eq(body.split("\"carrier\":\"relation\"").length(), 2)
    assert_eq(body.split("\"stage\":\"capture\"").length(), 2)
  }
}

///|
test "DATA JOIN shares alias ORDER resolution and hides sort slots" {
  for
    suffix in [
      "SELECT l.x AS y FROM seed AS l JOIN seed AS r ON l.x = r.x ORDER BY y + 1",
      "SELECT l.x + 1 AS a, l.x + 1 AS b FROM seed AS l JOIN seed AS r ON l.x = r.x ORDER BY l.x + 1",
      "SELECT l.x AS y FROM seed AS l JOIN seed AS r ON l.x = r.x ORDER BY l.y + 1",
    ] {
    let program = checked_data_join(
      "DATA seed = FROM t |> SELECT x, y; DATA joined = " +
      suffix +
      "; FROM joined |> SELECT *",
      join_order_context(),
    )
    let body = semantic(program)
    assert_eq(@program.stage_count(program), 1)
    assert_true(body.contains("aql_join_sorted_"))
    if !suffix.contains("ORDER BY l.x + 1") {
      assert_true(body.contains("aql_join_visible_"))
    }
    assert_false(body.contains("\"fields\":[\"aql_join_sort_"))
    if suffix.contains("ORDER BY y + 1") {
      assert_false(body.contains("left.y"))
    }
  }
}

///|
test "DATA JOIN refuses invalid names and output limits without fallback" {
  for
    text in [
      "DATA seed = FROM orders |> SELECT id; DATA joined = SELECT a.id FROM seed AS a JOIN seed AS a ON a.id = a.id; FROM joined |> SELECT id",
      "DATA seed = FROM orders |> SELECT id; DATA joined = SELECT id FROM seed AS a JOIN seed AS b ON a.id = b.id; FROM joined |> SELECT id",
      "DATA seed = FROM orders |> SELECT id; DATA joined = SELECT a.amount FROM seed AS a JOIN seed AS b ON a.id = b.id; FROM joined |> SELECT amount",
      "DATA seed = FROM orders |> SELECT id; DATA joined = SELECT a.id FROM seed AS a JOIN missing AS b ON a.id = b.id; FROM joined |> SELECT id",
    ] {
    assert_true(
      compile_query_script(
        @query.parse_query_script(text, syntax_limits()).unwrap(),
        fixture_context(),
        construction_limits(),
      )
      is Err(_),
      msg=text,
    )
  }
  let script = @query.parse_query_script(
    "DATA seed = FROM orders |> SELECT id; SELECT a.id FROM seed AS a JOIN seed AS b ON a.id = b.id",
    syntax_limits(),
  ).unwrap()
  assert_true(
    compile_query_script(script, fixture_context(), {
      ..construction_limits(),
      max_join_output_rows: 0L,
    })
    is Err(_),
  )
}
